@'
import assert from 'node:assert/strict';
import {restoreGraph, starter} from './frontend/src/js/alloy-graph.js';
import {createStudioRuns} from './frontend/src/js/alloy-runs.js';

const old = structuredClone(starter());
delete old.nodes.find(node => node.type === 'sources').settings.namedMobility;
delete old.nodes.find(node => node.type === 'sources').settings.configuredPhysical;
delete old.nodes.find(node => node.type === 'schedule').settings.events;
delete old.nodes.find(node => node.type === 'schedule').settings.route;
const graph = restoreGraph(old);
const equilibrium = graph.nodes.find(node => node.type === 'equilibrium');
const schedule = graph.nodes.find(node => node.type === 'schedule');
const source = graph.nodes.find(node => node.type === 'sources');
const runner = createStudioRuns(() => graph, () => {}, () => {}, () => undefined);
assert.deepEqual(source.settings, {family: 'AL', namedMobility: true, configuredPhysical: true});
assert.equal(schedule.settings.route, 'arc_melting');
assert.deepEqual(schedule.settings.events, []);
runner.results.set(equilibrium.id, {key: JSON.stringify({
  family:'AL', database_id:null, composition_mode:'fixed', composition_basis:'mass',
  additions:[{element:'CU', minimum:4, maximum:4}], route:'arc_melting',
  initial_temperature_k:298.15, melt_temperature_k:1873.15, final_temperature_k:298.15,
  pressure_pa:101325, cooling_points:21, include_reference_properties:false,
  allow_screening_estimates:false, use_physical_density:true
