import {restoreScheduleEvents} from './processing-events.js';

const pin = (label, type) => ({label, type});
const phase = pin('Phase Set', 'phase');
const assessment = pin('Assessment', 'assessment');
const physical = pin('Physical Data', 'physical');
const mobility = pin('Mobility Data', 'mobility');
export const families = ['AL', 'FE', 'MG', 'MO', 'NI', 'TI'];
export const operations = {
  composition: {title: 'Composition', group: 'input', outputs: {composition: pin('Composition', 'composition')},
    settings: {base: 'AL', element: 'CU', amount: 4, basis: 'mass'}},
  sources: {title: 'Data Sources', group: 'source', inputs: {
    assessment: pin('Thermodynamic File', 'assessment'), physical: pin('Physical Data File', 'physical'),
    mobility: pin('Mobility File', 'mobility')}, outputs: {assessment, physical, mobility},
    settings: {family: '', namedMobility: false, configuredPhysical: false}},
  assessmentFile: {title: 'Thermodynamic File', group: 'source', outputs: {file: assessment}, settings: {file: null}},
  physicalFile: {title: 'Physical Data File', group: 'source', outputs: {file: physical}, settings: {file: null}},
  mobilityFile: {title: 'Mobility File', group: 'source', outputs: {file: mobility}, settings: {file: null}},
  schedule: {title: 'Processing Schedule', group: 'input', outputs: {schedule: pin('Schedule', 'schedule')},
    settings: {initial: 298.15, melt: 1873.15, final: 298.15, pressure: 101325, points: 21, route: 'arc_melting', events: []}},
  equilibrium: {title: 'Equilibrium Along Schedule', group: 'model', run: true, inputs: {
    composition: pin('Composition', 'composition'), assessment, schedule: pin('Schedule', 'schedule')},
    outputs: {phase: {...phase, label: 'Final Phase Set'}}, settings: {}},
  density: {title: 'Density', group: 'property', run: true, inputs: {phase, physical},
    outputs: {result: pin('Density', 'density')}, settings: {references: true, parentDensity: false}},
  tracer: {title: 'Tracer Diffusivity', group: 'property', run: true, inputs: {phase, mobility},
    outputs: {result: pin('Tracer Diffusivities', 'tracer')}, settings: {}},
  viewer: {title: 'Phase Viewer', group: 'viewer', inputs: {phase}, settings: {}},
};

export function nodeOf(type, x, y, id = crypto.randomUUID()) {
  return {id, type, x, y, settings: structuredClone(operations[type].settings)};
}

const starterSourceY = 234;
const starterScheduleY = 490;

export function starter() {
  const sources = nodeOf('sources', 0, starterSourceY, 'sources');
  Object.assign(sources.settings, {family: 'AL', namedMobility: true, configuredPhysical: true});
  return {version: 1, name: 'Al–Cu equilibrium', nodes: [
    nodeOf('composition', 0, 0, 'composition'), sources,
    nodeOf('schedule', 0, starterScheduleY, 'schedule'), nodeOf('equilibrium', 314, 211, 'equilibrium'),
    nodeOf('viewer', 628, 0, 'viewer'), nodeOf('density', 628, 128, 'density'),
    nodeOf('tracer', 628, 320, 'tracer'),
  ], edges: [
    ['composition', 'composition', 'equilibrium', 'composition'],
    ['sources', 'assessment', 'equilibrium', 'assessment'],
    ['schedule', 'schedule', 'equilibrium', 'schedule'],
    ['equilibrium', 'phase', 'viewer', 'phase'],
    ['equilibrium', 'phase', 'density', 'phase'],
    ['equilibrium', 'phase', 'tracer', 'phase'],
    ['sources', 'physical', 'density', 'physical'],
    ['sources', 'mobility', 'tracer', 'mobility'],
  ]};
}

export function accepts(graph, edge) {
  const [from, output, to, input] = edge;
  const source = graph.nodes.find(node => node.id === from);
  const target = graph.nodes.find(node => node.id === to);
  const left = operations[source?.type]?.outputs?.[output];
  const right = operations[target?.type]?.inputs?.[input];
  if (!left || !right || left.type !== right.type) return false;
  const pending = [to], seen = new Set();
  while (pending.length) {
    const id = pending.pop();
    if (id === from) return false;
    if (seen.has(id)) continue;
    seen.add(id);
    pending.push(...graph.edges.filter(wire => wire[0] === id).map(wire => wire[2]));
  }
  return true;
}

export function restoreGraph(data) {
  if (data?.version !== 1 || typeof data.name !== 'string' || !Array.isArray(data.nodes) ||
      !Array.isArray(data.edges) || data.nodes.length > 100 || data.edges.length > 300) throw new Error('Invalid Alloy Studio workflow.');
  const graph = {version: 1, name: data.name.slice(0, 100), nodes: [], edges: []};
  for (const node of data.nodes) {
    if (!Object.hasOwn(operations, node.type) || typeof node.id !== 'string' || !/^[\w-]{1,64}$/.test(node.id) ||
        graph.nodes.some(peer => peer.id === node.id) || !Number.isFinite(node.x) || !Number.isFinite(node.y)) {
      throw new Error('The workflow has an invalid node.');
    }
    const restored = nodeOf(node.type, Math.max(-10000, Math.min(10000, node.x)), Math.max(-10000, Math.min(10000, node.y)), node.id);
    for (const [key, initial] of Object.entries(restored.settings)) {
      const value = node.settings?.[key];
      if (key === 'events') {
        restored.settings.events = restoreScheduleEvents(value);
      } else if (key === 'route') {
        if (value === 'heat_treatment') restored.settings.route = value;
      } else if (node.type === 'schedule' && typeof initial === 'number' && value === null) {
        restored.settings[key] = null;
      } else if (initial === null) {
        if (typeof value?.id === 'string' && /^[a-f0-9]{64}$/.test(value.id) && typeof value.name === 'string') {
          restored.settings[key] = {id: value.id, name: value.name.slice(0, 240)};
        }
      } else if (typeof value === typeof initial && (typeof value !== 'number' || Number.isFinite(value))) {
        restored.settings[key] = value;
      }
    }
    if (node.type === 'sources' && families.includes(restored.settings.family)) {
      restored.settings.namedMobility = node.settings?.namedMobility !== false;
      restored.settings.configuredPhysical = node.settings?.configuredPhysical !== false;
    }
    graph.nodes.push(restored);
  }
  for (const edge of data.edges) {
    if (!Array.isArray(edge) || edge.length < 4 || edge.length > 5 || !accepts(graph, edge) ||
        graph.edges.some(wire => wire[2] === edge[2] && wire[3] === edge[3])) throw new Error('The workflow has an invalid connection.');
    const [from, output, to, input, route = []] = edge;
    if (!Array.isArray(route) || route.length > 100 ||
        route.some(point => !Number.isFinite(point?.x) || !Number.isFinite(point?.y))) {
      throw new Error('The workflow has an invalid wire route.');
    }
    const wire = [from, output, to, input];
    if (route.length) wire.push(route.map(({x, y}) => ({
      x: Math.max(-10000, Math.min(10000, x)), y: Math.max(-10000, Math.min(10000, y)),
    })));
    graph.edges.push(wire);
  }
  // Older starters used shorter summary-only cards. Expand the original
  // left column when those cards still occupy their original positions.
  const original = (id, ys) => graph.nodes.find(node => node.id === id && node.type === id && node.x === 0 && ys.includes(node.y));
  const source = original('sources', [129]);
  const schedule = original('schedule', [313, 363]);
  if (original('composition', [0]) && source && schedule) {
    source.y = starterSourceY;
    schedule.y = starterScheduleY;
  }
  return graph;
}
import {families} from './alloy-graph.js';
import {scheduleIssue} from './processing-events.js';

export async function studioApi(path, options) {
  const response = await fetch(path, options);
  const value = await response.json();
  if (!response.ok) {
    const detail = Array.isArray(value.detail) ? value.detail.map(item => `${item.loc.at(-1)}: ${item.msg}`).join(' · ') : value.detail;
    throw new Error(detail || 'The server could not complete the request.');
  }
  return value;
}

export function studioPost(path, body) {
  return studioApi(path, {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(body)});
}

export function createStudioRuns(getGraph, changed, report, getSourceCatalog) {
  const results = new Map();
  let activeJob = null, cancelled = false;
  const nodeById = id => getGraph().nodes.find(node => node.id === id);
  const upstream = (node, pin) => nodeById(getGraph().edges.find(edge => edge[2] === node.id && edge[3] === pin)?.[0]);

  function sourceInput(node, role) {
    const connected = node.type === 'sources' ? upstream(node, role) : node;
    if (connected) {
      const file = connected.settings.file;
      return file ? {name: file.name, file} : {issue: `Choose the connected ${role} file.`};
    }
    const {family, namedMobility, configuredPhysical} = node.settings;
    const catalog = getSourceCatalog();
    const preset = catalog?.sources.find(item => item.family === family);
    if (role === 'assessment') {
      if (!families.includes(family)) return {issue: 'Choose a thermodynamic assessment.'};
      return {name: preset?.thermodynamic || `MatCalc ${family}`,
        issue: preset?.available === false ? `${preset.thermodynamic} is unavailable.` : null};
    }
    if (role === 'mobility') {
      if (!namedMobility || !families.includes(family) || upstream(node, 'assessment')) {
        return {issue: 'Choose a compatible mobility file.'};
      }
      return {name: preset?.mobility || 'Named companion',
        issue: preset?.mobility_available === false ? `${preset.mobility} is unavailable.` : null};
    }
    if (!configuredPhysical) return {issue: 'Choose a physical data file.'};
    return {name: catalog?.physical?.name || 'Configured physical data',
      issue: catalog?.physical?.available === false ? `${catalog.physical.name} is unavailable.` : null};
  }

  function requiredSource(node, role) {
    const input = sourceInput(node, role);
    if (input.issue) throw new Error(input.issue);
    return input;
  }

  function equilibriumRequest(node) {
    const alloy = upstream(node, 'composition')?.settings;
    const schedule = upstream(node, 'schedule')?.settings;
    const source = upstream(node, 'assessment');
    if (!alloy) throw new Error('Connect Composition.');
    if (!source) throw new Error('Connect a thermodynamic assessment.');
    if (!schedule) throw new Error('Connect Processing Schedule.');
    const assessment = requiredSource(source, 'assessment');
    const family = alloy.base;
    if (!assessment.file && family !== source.settings.family) throw new Error('The composition base element must match the assessment family.');
    if (!families.includes(family)) throw new Error('Choose a supported base element.');
    const element = alloy.element.trim().toUpperCase();
    if (!/^[A-Z]{1,2}$/.test(element) || element === alloy.base || !(alloy.amount > 0 && alloy.amount < 100)) {
      throw new Error('Enter a distinct alloying element and an addition between 0 and 100%.');
    }
    const issue = scheduleIssue(schedule);
    if (issue) throw new Error(issue);
    return {
      family, database_id: assessment.file?.id ?? null, composition_mode: 'fixed', composition_basis: alloy.basis,
      additions: [{element, minimum: alloy.amount, maximum: alloy.amount}], route: schedule.route,
      initial_temperature_k: schedule.initial,
      ...(schedule.route === 'arc_melting' ? {melt_temperature_k: schedule.melt, final_temperature_k: schedule.final} : {}),
      pressure_pa: schedule.pressure,
      ...(schedule.route === 'arc_melting' ? {cooling_points: schedule.points} : {}),
      ...(schedule.events.length ? {events: schedule.events} : {}),
      include_reference_properties: false, allow_screening_estimates: false, use_physical_density: true,
    };
  }

  function jobInputs(node) {
    if (node.type === 'equilibrium') return equilibriumRequest(node);
    const equilibrium = upstream(node, 'phase');
    if (!equilibrium) throw new Error('Connect an equilibrium Phase Set.');
    const phaseSource = upstream(equilibrium, 'assessment');
    const role = node.type === 'density' ? 'physical' : 'mobility';
    const source = upstream(node, role);
    if (node.type === 'tracer' && !source) throw new Error('Connect Mobility Data or a Mobility File.');
    const input = source && requiredSource(source, role);
    if (role === 'mobility' && input && !input.file && source.id !== phaseSource?.id) {
      throw new Error('Use the assessment’s named mobility companion or connect an explicit mobility file.');
    }
    const saved = current(equilibrium);
    return {equilibrium_job: saved?.job ?? null, operation: node.type,
      companion_id: input?.file?.id ?? null, use_physical_density: Boolean(source),
      allow_parent_density: node.type === 'density' && node.settings.parentDensity,
      include_reference_properties: node.type === 'density' && node.settings.references};
  }

  function signature(node) {
    return JSON.stringify(jobInputs(node));
  }

  function inputIssue(node) {
    try {
      if (node.type === 'viewer') return upstream(node, 'phase') ? null : 'Connect an equilibrium Phase Set.';
      jobInputs(node);
      if (node.type !== 'equilibrium') equilibriumRequest(upstream(node, 'phase'));
      return null;
    } catch (error) { return error.message; }
  }

  function current(node) {
    const saved = results.get(node.id);
    if (!saved) return null;
    try { return saved.key === signature(node) ? saved : null; }
    catch { return null; }
  }

  async function perform(node, force = false) {
    if (cancelled) return;
    if (node.type !== 'equilibrium') {
      // Validate branch connections before spending time on its prerequisite.
      jobInputs(node);
      const equilibrium = upstream(node, 'phase');
      if (!current(equilibrium)) await perform(equilibrium);
    }
    if (cancelled || (!force && current(node))) return;
    const input = jobInputs(node);
    const key = JSON.stringify(input);
    const path = node.type === 'equilibrium' ? '/api/workflow/equilibrium' : '/api/workflow/branch';
    report(node, 'Submitting…');
    const job = await studioPost(path, input);
    activeJob = job.id;
    try {
      if (cancelled) await studioApi(`/api/jobs/${activeJob}`, {method: 'DELETE'});
      while (true) {
        const status = await studioApi(`/api/jobs/${activeJob}`);
        if (status.state === 'cancelled') {
          cancelled = true;
          report(node, 'Canceled');
          return;
        }
        if (status.state === 'failed') throw new Error(status.error || 'Calculation failed.');
        if (status.state === 'completed') {
          const result = await studioApi(`/api/jobs/${activeJob}/result`);
          results.set(node.id, {job: activeJob, key, result});
          changed();
          const unavailable = result.kawin?.state === 'unavailable' ||
            (result.properties && result.properties.density?.state !== 'estimated');
          report(node, unavailable ? 'Unavailable · inspect coverage' : 'Complete', 100);
          return;
        }
        report(node, status.message || 'Preparing calculation…', status.percent);
        await new Promise(resolve => setTimeout(resolve, 320));
      }
    } finally {
      activeJob = null;
    }
  }

  return {
    results, current, upstream, inputIssue, sourceInput,
    async run(targets, force) {
      cancelled = false;
      for (const node of targets) {
        if (cancelled) break;
        try { await perform(node, force); }
        catch (error) { report(node, error.message, undefined, true); }
      }
    },
    async cancel() {
      cancelled = true;
      if (activeJob) await studioApi(`/api/jobs/${activeJob}`, {method: 'DELETE'});
    },
    async restore(entries) {
      for (const [id, saved] of entries) {
        if (!nodeById(id) || typeof saved?.job !== 'string' || typeof saved.key !== 'string' ||
            !/^[a-f0-9-]{36}$/.test(saved.job)) continue;
        try {
          const result = await studioApi(`/api/jobs/${saved.job}/result`);
          results.set(id, {...saved, result});
        } catch {
          // Graphs remain editable when an earlier run was removed from disk.
        }
      }
    },
  };
}

