"""Server-only Materials Project reference acquisition; credentials never cached."""
from datetime import datetime, timezone
import hashlib
import json
from time import time

import requests

from rutile3.jobs.storage import read_json, write_json


class ReferenceUnavailable(ValueError):
    pass


_SUMMARY_FIELDS = "material_id,formula_pretty,composition,density,symmetry,energy_above_hull,deprecated"


def elasticity_records(client, identifiers, payloads):
    """Read bounded batches and reject ambiguous records independently of API order."""
    records = {}
    identifiers = sorted(set(identifiers))
    for start in range(0, len(identifiers), 100):
        batch = identifiers[start:start + 100]
        payload = client.elasticity(batch)
        payloads.append(payload)
        if payload.get("api_meta", {}).get("total_doc", 0) > len(payload["data"]):
            raise ReferenceUnavailable("Materials Project elasticity response was truncated.")
        for document in payload["data"]:
            identifier = document["material_id"]
            if identifier in batch:
                records[identifier] = document if identifier not in records else None
    return records


class MaterialsProject:
    def __init__(self, key, cache):
        self.key = key
        self.cache = cache
        self.session = requests.Session()

    def get(self, endpoint, params):
        identity = hashlib.sha256(json.dumps([endpoint, params], sort_keys=True).encode()).hexdigest()
        path = self.cache / f"{identity}.json"
        if path.exists():
            try:
                cached = read_json(path)
                if 0 <= time() - cached["cached_at"] < 7 * 86400:
                    return cached["payload"]
            except (OSError, ValueError, KeyError, TypeError):
                pass
        try:
            response = self.session.get(f"https://api.materialsproject.org/materials/{endpoint}/",
                                       headers={"X-API-KEY": self.key}, params=params, timeout=(8, 25))
        except requests.RequestException:
            raise ReferenceUnavailable("Materials Project could not be reached.") from None
        if response.status_code in {401, 403}:
            raise ReferenceUnavailable("Materials Project rejected the configured credential or access permission.")
        if response.status_code == 429:
            raise ReferenceUnavailable("Materials Project rate limit reached. Try again later.")
        if not response.ok:
            raise ReferenceUnavailable(f"Materials Project returned HTTP {response.status_code}.")
        try:
            body = response.json()
            if not isinstance(body.get("data"), list):
                raise ValueError()
        except (ValueError, AttributeError):
            raise ReferenceUnavailable("Materials Project returned an invalid data response.") from None
        payload = {"data": body["data"], "api_meta": body.get("meta", {}),
                   "retrieved_at": datetime.now(timezone.utc).isoformat(), "endpoint": endpoint,
                   "query": params}
        try:
            self.cache.mkdir(parents=True, exist_ok=True)
            write_json(path, {"cached_at": time(), "payload": payload})
        except OSError:
            pass  # Read-only caches must not invalidate reference results.
        return payload

    def summary(self, elements):
        return self.get("summary", {"chemsys": "-".join(sorted(e.title() for e in elements)),
            "deprecated": False, "_limit": 1000, "_fields": _SUMMARY_FIELDS})

    def elastic_summary(self, systems, space_group):
        return self.get("summary", {
            "chemsys": ",".join(sorted("-".join(sorted(e.title() for e in system)) for system in systems)),
            "has_props": "elasticity", "spacegroup_number": space_group,
            "deprecated": False, "_limit": 1000, "_fields": _SUMMARY_FIELDS,
        })

    def elasticity(self, identifiers):
        return self.get("elasticity", {"material_ids": ",".join(sorted(identifiers)), "_limit": 1000,
            "_fields": "material_id,bulk_modulus,shear_modulus,elastic_tensor,deprecated"})
"""Short JSON reads and atomic writes tolerant of Windows sharing locks."""
import json
from pathlib import Path
from tempfile import NamedTemporaryFile
from time import sleep


def retry_io(operation, attempts=9):
    for attempt in range(attempts):
        try:
            return operation()
        except PermissionError:
            if attempt == attempts-1:
                raise
            sleep(min(.01 * 2**attempt, .16))


def read_json(path):
    # Close the handle before returning, particularly before streaming HTTP data.
    return retry_io(lambda: json.loads(path.read_text(encoding="utf-8")))


def write_json(path, value):
    content = json.dumps(value, allow_nan=False)
    with NamedTemporaryFile(mode="w", encoding="utf-8", dir=path.parent,
                            prefix=path.stem+"-", suffix=".tmp", delete=False) as stream:
        temporary = Path(stream.name)
        stream.write(content)
    try:
        retry_io(lambda: temporary.replace(path))
    finally:
        if temporary.exists():
            retry_io(temporary.unlink)
import json
import os
import signal
from pathlib import Path
import subprocess
import sys
from threading import RLock
from uuid import UUID, uuid4

from rutile3.data.catalog import WORKSPACE
from rutile3.jobs.storage import read_json, write_json


class JobManager:
    def __init__(self):
        self.processes = {}
        self.lock = RLock()

    def folder(self, job_id):
        UUID(job_id)
        folder = WORKSPACE / "runs" / job_id
        if not folder.exists():
            raise ValueError("Calculation not found.")
        return folder

    def start(self, path, settings, decision, *, snapshot=None, kind="diagram", mobility=None, api_key=None, physical=None,
              upstream=None):
        with self.lock:
            if any(process.poll() is None and self.status(key)["state"] == "running"
                   for key, process in self.processes.items()):
                raise ValueError("A calculation is already running. Wait or cancel it first.")
            job_id = str(uuid4())
            folder = WORKSPACE / "runs" / job_id
            folder.mkdir(parents=True)
            source = Path(path)
            if snapshot is not None:
                path = folder / ("tensile-source" if kind == "mechanical" else "source.tdb")
                path.write_bytes(snapshot)
            if mobility is not None:
                (folder / "source.ddb").write_bytes(mobility["raw"])
            if physical is not None:
                (folder / "physical-source.pdb").write_bytes(physical["raw"])
                if physical.get("description"):
                    (folder / "physical-source-description.md").write_text(physical["description"], encoding="utf-8")
            if upstream is not None:
                write_json(folder / "upstream.json", upstream)
            (folder / "request.json").write_text(json.dumps({"database_path": str(path), "settings": settings,
                                                            "source_name": source.name,
                                                            "kind": kind,
                                                            "mobility_name": mobility["name"] if mobility else None,
                                                            "physical_name": physical["name"] if physical else None,
                                                            "selection": decision}), encoding="utf-8")
            (folder / "status.json").write_text(json.dumps({"state": "running", "completed_rows": 0,
                                                            "total_rows": settings.get("temperature_points", settings.get("cooling_points", 0))}), encoding="utf-8")
            with (folder / "worker.log").open("w", encoding="utf-8") as log:
                environment = os.environ.copy()
                if api_key:
                    environment["MP_API_KEY"] = api_key
                # Each process gets one native BLAS/OpenMP thread. Otherwise
                # nested pools can oversubscribe the CPU and reduce throughput.
                for name in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS", "NUMEXPR_NUM_THREADS"):
                    environment[name] = "1"
                self.processes[job_id] = subprocess.Popen(
                    [sys.executable, "-m", "rutile3.jobs.worker", str(folder)],
                    stdout=log, stderr=subprocess.STDOUT,
                    env=environment,
                    start_new_session=os.name != "nt",
                    creationflags=subprocess.CREATE_NO_WINDOW if os.name == "nt" else 0)
            return job_id

    def status(self, job_id):
        folder = self.folder(job_id)
        value = read_json(folder / "status.json")
        process = self.processes.get(job_id)
        if value["state"] == "running" and (process is None or process.poll() is not None):
            # The worker can finish between the first read and poll(). Re-read
            # its terminal status before interpreting a process exit as failure.
            value = read_json(folder / "status.json")
            if value["state"] == "running":
                if (folder / "result.json").exists():
                    read_json(folder / "result.json")  # Only recover a complete JSON artifact.
                    value = {"state": "completed"}
                elif process is None:
                    value = {"state": "failed", "error": "The application restarted before this calculation completed. Please run again."}
                else:
                    value = {"state": "failed", "worker_exit_code": process.returncode,
                             "error": f"Calculation worker exited (code {process.returncode}). See worker.log and error.log in the run folder."}
        return value

    def cancel(self, job_id):
        with self.lock:
            folder = self.folder(job_id)
            process = self.processes.get(job_id)
            if process and process.poll() is None and self.status(job_id)["state"] == "running":
                if os.name == "nt":
                    # Terminate the known job's process tree, including pool
                    # workers currently inside native scientific code.
                    stopped = subprocess.run(["taskkill", "/PID", str(process.pid), "/T", "/F"],
                                             capture_output=True, timeout=10,
                                             creationflags=subprocess.CREATE_NO_WINDOW)
                    if stopped.returncode and process.poll() is None:
                        process.terminate()
                else:
                    os.killpg(process.pid, signal.SIGTERM)
                process.wait(timeout=10)
                write_json(folder / "status.json", {"state": "cancelled"})
            return self.status(job_id)

    def close(self):
        for key in list(self.processes):
            self.cancel(key)

