const starterSourceY = 234;
const starterScheduleY = 490;

export function starter() {
  const sources = nodeOf('sources', 0, starterSourceY, 'sources');
  Object.assign(sources.settings, {family: 'AL', namedMobility: true, configuredPhysical: true});
  return {version: 2, name: 'Al–Cu equilibrium', nodes: [
    nodeOf('composition', 0, 0, 'composition'), sources,
    nodeOf('schedule', 0, starterScheduleY, 'schedule'), nodeOf('equilibrium', 314, 211, 'equilibrium'),
    nodeOf('phaseAssignment', 628, 211, 'phase-assignment'),
    nodeOf('viewer', 942, 0, 'viewer'), nodeOf('density', 942, 128, 'density'),
    nodeOf('tracer', 942, 320, 'tracer'),
