    })];
    const checkbox = (key, text, disabled = false) => `<label><input type="checkbox" data-field="${key}"
      ${s[key] && !disabled ? 'checked' : ''} ${disabled ? 'disabled data-source-locked' : ''}> ${esc(text)}</label>`;
    return Object.entries(sourceLabels).map(([role, label]) => {
      const input = runs.sourceInput(node, role);
      const wired = runs.upstream(node, role);
      const control = wired ? `<p>${esc(input.name || input.issue)}</p>` : {
        assessment: selectField(s, 'family', 'Assessment', files),
        mobility: manualAssessment ? `<p class="fine">${esc(input.issue)}</p>` :
          checkbox('namedMobility', preset?.mobility || 'Use the assessment’s named mobility companion', !s.family),
        physical: checkbox('configuredPhysical', catalog?.physical?.name || 'Use configured physical data'),
      }[role];
      return `<div class="studio-source-setting"><h4>${label}</h4>${control}
        ${input.issue && input.name ? `<p class="fine">${esc(input.issue)}</p>` : ''}</div>`;
