const cmd=`@'
import assert from 'node:assert/strict';
import {accepts, nodeOf, restoreGraph, starter} from './frontend/src/js/alloy-graph.js';
import {phaseDataRequest} from './frontend/src/js/alloy-phase-data.js';
const fresh = starter();
assert.deepEqual(restoreGraph(fresh), fresh);
const fileIds = {'assessment-file':'assessment','mobility-file':'mobility','physical-file':'physical'};
const legacy = {version:2, name:fresh.name, nodes:fresh.nodes.filter(n => !fileIds[n.id] && n.type !== 'phaseData'),
  edges:fresh.edges.filter(e => !e[3].startsWith('record_')).map(e => fileIds[e[0]] ? ['sources',fileIds[e[0]],...e.slice(2)] : e)};
const sources = nodeOf('sources',0,234,'sources');
Object.assign(sources.settings,{family:'AL',namedMobility:true,configuredPhysical:true});
legacy.nodes.push(sources);
const migrated = restoreGraph(legacy);
assert.equal(migrated.version,3);
assert.ok(!migrated.nodes.some(n=>n.type==='sources'));
assert.deepEqual(migrated.nodes.filter(n=>n.type.endsWith('File')).map(n=>[n.type,n.settings.preset]),[
 ['assessmentFile','AL'],['mobilityFile','AL'],['physicalFile','configured']
]);
assert.equal(migrated.edges.filter(e=>e[3].startsWith('record_')).length,2);
assert.ok(migrated.edges.every(e=>accepts(migrated,e)));
const uploaded = nodeOf('assessmentFile',-100,250,'old-upload');
uploaded.settings.file = {id:'a'.repeat(64),name:'sample.tdb'};
legacy.nodes.push(uploaded);
legacy.edges.push([uploaded.id,'file','sources','assessment']);
const withOverride = restoreGraph(legacy);
assert.ok(withOverride.edges.some(e=>e[0]===uploaded.id && e[2]==='equilibrium'));
assert.equal(withOverride.nodes.find(n=>n.type==='mobilityFile').settings.preset,'');
const phase = nodeOf('phaseData',0,0);
phase.settings.materialId='https://www.materialsproject.org/materials/mp-998/?from=test';
assert.deepEqual(phaseDataRequest(phase.settings),{material_id:'mp-998',data:null});
console.log('PASS saved workflow migration, upload preservation, and phase reference URL parsing');
